[query_table_names]
SELECT t.name AS table_name FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id WHERE s.name = ? AND UPPER(t.name) LIKE ?

[query_table_columns]
SELECT c.column_id AS column_id, c.name AS column_name, ty.name AS type_name, c.max_length AS max_length, c.precision AS precision, c.scale AS scale, c.is_nullable AS is_nullable, c.is_identity AS is_identity, c.is_sparse AS is_sparse, c.is_rowguidcol AS is_rowguidcol, c.is_filestream AS is_filestream, ic.seed_value AS identity_seed, ic.increment_value AS identity_increment, dc.definition AS default_definition, cc.definition AS computed_definition, cc.is_persisted AS computed_persisted FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.columns c ON c.object_id = t.object_id JOIN sys.types ty ON ty.user_type_id = c.user_type_id LEFT JOIN sys.identity_columns ic ON ic.object_id = c.object_id AND ic.column_id = c.column_id LEFT JOIN sys.default_constraints dc ON dc.parent_object_id = c.object_id AND dc.parent_column_id = c.column_id LEFT JOIN sys.computed_columns cc ON cc.object_id = c.object_id AND cc.column_id = c.column_id WHERE s.name = ? AND UPPER(t.name) = ? ORDER BY c.column_id

[query_table_indexes]
SELECT i.name AS index_name, i.is_primary_key AS is_primary_key, i.is_unique_constraint AS is_unique_constraint, i.is_unique AS is_unique, i.type_desc AS type_desc, i.has_filter AS has_filter, i.filter_definition AS filter_definition, STUFF((SELECT ',' + QUOTENAME(col.name) + CASE WHEN ic2.is_descending_key = 1 THEN ' DESC' ELSE ' ASC' END FROM sys.index_columns ic2 JOIN sys.columns col ON col.object_id = ic2.object_id AND col.column_id = ic2.column_id WHERE ic2.object_id = i.object_id AND ic2.index_id = i.index_id AND ic2.is_included_column = 0 ORDER BY ic2.key_ordinal FOR XML PATH('')), 1, 1, '') AS index_columns, STUFF((SELECT ',' + QUOTENAME(col.name) FROM sys.index_columns ic3 JOIN sys.columns col ON col.object_id = ic3.object_id AND col.column_id = ic3.column_id WHERE ic3.object_id = i.object_id AND ic3.index_id = i.index_id AND ic3.is_included_column = 1 ORDER BY ic3.index_column_id FOR XML PATH('')), 1, 1, '') AS included_columns FROM sys.indexes i JOIN sys.tables t ON t.object_id = i.object_id JOIN sys.schemas s ON s.schema_id = t.schema_id WHERE s.name = ? AND UPPER(t.name) = ? AND i.type > 0 AND i.is_hypothetical = 0 AND i.name IS NOT NULL ORDER BY i.index_id

[query_table_triggers]
SELECT tr.name AS trigger_name, tr.is_disabled AS is_disabled, OBJECT_DEFINITION(tr.object_id) AS trigger_def FROM sys.triggers tr JOIN sys.tables t ON t.object_id = tr.parent_id JOIN sys.schemas s ON s.schema_id = t.schema_id WHERE s.name = ? AND UPPER(t.name) = ?

[query_table_foreign_keys]
SELECT fk.name AS constraint_name, 'FOREIGN KEY (' + STUFF((SELECT ',' + QUOTENAME(pc.name) FROM sys.foreign_key_columns fkc JOIN sys.columns pc ON pc.object_id = fkc.parent_object_id AND pc.column_id = fkc.parent_column_id WHERE fkc.constraint_object_id = fk.object_id ORDER BY fkc.constraint_column_id FOR XML PATH('')), 1, 1, '') + ') REFERENCES ' + QUOTENAME(SCHEMA_NAME(rt.schema_id)) + '.' + QUOTENAME(rt.name) + ' (' + STUFF((SELECT ',' + QUOTENAME(rc.name) FROM sys.foreign_key_columns fkc JOIN sys.columns rc ON rc.object_id = fkc.referenced_object_id AND rc.column_id = fkc.referenced_column_id WHERE fkc.constraint_object_id = fk.object_id ORDER BY fkc.constraint_column_id FOR XML PATH('')), 1, 1, '') + ')' + CASE WHEN fk.delete_referential_action_desc = 'CASCADE' THEN ' ON DELETE CASCADE' WHEN fk.delete_referential_action_desc = 'SET_NULL' THEN ' ON DELETE SET NULL' WHEN fk.delete_referential_action_desc = 'SET_DEFAULT' THEN ' ON DELETE SET DEFAULT' ELSE '' END + CASE WHEN fk.update_referential_action_desc = 'CASCADE' THEN ' ON UPDATE CASCADE' WHEN fk.update_referential_action_desc = 'SET_NULL' THEN ' ON UPDATE SET NULL' WHEN fk.update_referential_action_desc = 'SET_DEFAULT' THEN ' ON UPDATE SET DEFAULT' ELSE '' END AS constraint_def FROM sys.foreign_keys fk JOIN sys.tables t ON t.object_id = fk.parent_object_id JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.tables rt ON rt.object_id = fk.referenced_object_id WHERE s.name = ? AND UPPER(t.name) = ?
